/***************************/
  /***** Login Page *****/
/**************************/
.login-bg {
  background: linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 100%);
  font-family: Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  width: 100vw;
  height: 100vh;
  margin: 0;
  padding: 2px;
}

.login-left {
  padding-left: 1.5rem !important;
  padding-right: 1.5rem !important;
  padding-top: .1rem !important;
  padding-bottom: .1rem !important;
}

.login-logo-box {
  height: 50px;
  margin-bottom: 30px;
  width: 110px;
  background-color: #0c3064;
  border-radius: 8px;
  display: flex;
  align-items: center;
}

.login-signup-link {
  text-decoration: none;
  font-size: 14px;
}

.login-divider {
  width: 1px;
  background: #e0e0e0;
  min-height: 5%;
  margin: 0 0px;
}

.login-right {
  background-color: #f8f9fa;
}


/******************************************/
/* Signup page logo box - desktop styles */
/*****************************************/

.signup-logo-box {
  height: 50px;
  margin-bottom: 30px;
  width: 75px;
  background-color: #0c3064;
  border-radius: 8px;
  display: flex;
  align-items: center;
}


.card-container {
  max-width: 1000px;
  min-width: 700px;
}

/*********************/
/* Registeration Page */
/*********************/
.registeration-bg {
  --bs-font-size-sm: 16px; 
}

.registeration-bg .fw-semibold {
  font-weight: 700 !important; 
}

.registeration-bg .small {
  font-size: 14px !important; 
}

.registeration-bg .form-control,
.registeration-bg .form-select {
  font-size: 17px !important;
  font-weight: 500 !important;
}

.registeration-bg .text-muted {
  font-size: 13px !important;
  font-weight: 400 !important;
}

.registeration-bg h6 {
  font-size: 22px !important;
  font-weight: 700 !important;
}

.registeration-bg h4 {
  font-size: 24px !important;
  font-weight: 700 !important;
}

.registeration-logo-box {
  border-radius: 8px;
  display: flex;
  align-items: center;
  background-color: #0c3064;
  width:80px
}

@media (max-width: 575.98px) {

  .card-container {
    max-width: 100% !important;
    min-width: 100% !important;
    padding: 0.5rem !important;
  }
  

  .login-bg {
    padding: 8px !important;
  }
  

  .container .row .login-left,
  .container .row .col-md-7.login-left,
  div.row div.col-md-7 {
    padding: 0rem !important;
    max-width: 100% !important;
    flex: 0 0 100% !important;
    width: 100% !important;
    margin-left: 0 !important;
    margin-right: 0 !important;
    gap:15px;
  }
  

  .login-divider {
    display: none !important;
  }
  
  .container .row .login-right,
  .container .row .col-md-4.login-right,
  div.row div.col-md-4,
  .col-md-4.login-right {
    display: none !important;
    visibility: hidden !important;
    width: 0 !important;
    flex: 0 0 0% !important;
    max-width: 0 !important;
    overflow: hidden !important;
  }
  

  .login-logo-box {
    width: 100% !important;
    height: auto !important;
    margin-bottom: 20px !important;
    flex-direction: column !important;
    padding: 10px !important;
  }
  

  .login-logo-box .mb-4 {
    margin-bottom: 0 !important;
    flex-direction: column !important;
    align-items: center !important;
    text-align: center !important;
    gap: 20px !important;
  }
  

  .login-logo-box img {
    margin: 0 !important;
    margin-bottom: 8px !important;
  }
  

  .login-logo-box span {
    margin: 0 !important;
    text-align: center !important;
    font-size: 18px !important;
  }
  
 
  .login-logo-box div {
    flex-direction: column !important;
    align-items: center !important;
    text-align: center !important;
  }
  
  .login-logo-box div img {
    margin: 0 0 8px 0 !important;
  }
  
  .login-logo-box div span {
    margin: 0 !important;
    font-size: 20px !important;
    line-height: 1.2 !important;
    text-align: center !important;
    color: white !important;
  }
  
  
  .login-signup-link {
    font-size: 12px !important;
  }
  

  .card,
  .row {
    width: 100% !important;
    max-width: 100% !important;
  }
  
  [class*="col-md-4"] {
    display: none !important;
  }
  
  [class*="col-md-7"] {
    flex: 0 0 100% !important;
    max-width: 100% !important;
    width: 100% !important;
  }
  
  .signup-logo-box {
    width: 100% !important;
    height: 100px !important;
    margin-bottom: 20px !important;
    flex-direction: column !important;
    padding: 10px !important;
    margin-top: 10px;
  }
  
  .signup-logo-box .mb-4 {
    margin-bottom: 0 !important;
    flex-direction: column !important;
    align-items: center !important;
    text-align: center !important;
    gap: 20px !important;
  }
  
  .signup-logo-box img {
    margin: 0 !important;
    margin-bottom: 8px !important;
  }
  
  .signup-logo-box span {
    margin: 0 !important;
    text-align: center !important;
    font-size: 18px !important;
  }
  
  .signup-logo-box div {
    flex-direction: column !important;
    align-items: center !important;
    text-align: center !important;
  }
  
  .signup-logo-box div img {
    margin: 0 0 8px 0 !important;
  }
  
  .signup-logo-box div span {
    margin: 0 !important;
    font-size: 20px !important;
    line-height: 1.2 !important;
    text-align: center !important;
    color: white !important;
  }
}

@media (min-width: 576px) and (max-width: 768px) {
  .card-container {
    max-width: 90% !important;
    min-width: 600px;
  }
  
  .login-bg {
    padding: 4px;
  }
  
  .login-left {
    padding: 1.25rem !important;
    max-width: 65% !important;
    flex: 0 0 65% !important;
  }
  
  .login-logo-box {
    width: 70px;
    height: 45px;
    margin-bottom: 25px;
  }
  
  .login-right {
    max-width: 35% !important;
    flex: 0 0 35% !important;
  }
}

html, body {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

*, *::before, *::after {
  box-sizing: border-box;
}
